const listThreadsDueForArchive = `-- name: ListThreadsDueForArchive :many
SELECT id, COALESCE(parent_channel_id, 0) AS parent_id
FROM channels
WHERE type = 'thread' AND thread_archived = 0 AND thread_last_activity_at IS NOT NULL
  AND CAST(strftime('%s', thread_last_activity_at) AS INTEGER) + thread_auto_archive_minutes * 60 <= CAST(?1 AS INTEGER)
ORDER BY thread_last_activity_at ASC, id ASC
LIMIT ?2
`

